create table readings (id bigint generated always as identity primary key, org_id integer not null, kind text not null, taken_at timestamptz not null, watts integer, cost numeric(10,2), deleted_at timestamptz);
create index on readings (taken_at);
create index on readings (org_id);
insert into readings (org_id, kind, taken_at, watts, cost, deleted_at)
  select 1 + i % 2, case when i % 3 = 0 then 'heat' else 'power' end, timestamptz '2026-11-01 00:00:00+00' + i * interval '97 seconds',
    case when i % 7 = 0 then null else i % 500 end, (i % 1000) / 100.0, case when i % 11 = 0 then timestamptz '2026-11-05 00:00:00+00' end
  from generate_series(1, 6000) as i;
-- The buckets are UTC hours whatever the session's time zone, here one half an hour off.
set timezone = 'Asia/Kolkata';

create schema if not exists "rollups";

create table "public"."readings_hourly" ("id" bigint generated always as identity primary key, "bucket" timestamptz not null, "org_id" integer not null, "kind" text not null, "events" bigint not null, "watts_sum" bigint, "watts_max" integer, "cost_sum" numeric(20,2));

create unique index "readings_hourly_bucket_key" on "public"."readings_hourly" ("bucket", "org_id", "kind");

create index "readings_hourly_org_id_bucket" on "public"."readings_hourly" ("org_id", "bucket");

create index "readings_hourly_kind_bucket" on "public"."readings_hourly" ("kind", "bucket");

comment on table "public"."readings_hourly" is 'protobase time rollup: create table "public"."readings_hourly" ("id" bigint generated always as identity primary key, "bucket" timestamptz not null, "org_id" integer not null, "kind" text not null, "events" bigint not null, "watts_sum" bigint, "watts_max" integer, "cost_sum" numeric(20,2)); create unique index "readings_hourly_bucket_key" on "public"."readings_hourly" ("bucket", "org_id", "kind"); create index "readings_hourly_org_id_bucket" on "public"."readings_hourly" ("org_id", "bucket"); create index "readings_hourly_kind_bucket" on "public"."readings_hourly" ("kind", "bucket")';

create or replace function "rollups"."readings_hourly_refresh"("from" timestamptz) returns void language sql set search_path = pg_catalog, pg_temp set timezone = 'UTC' as $buckets$
with fresh as (
  select date_trunc('hour', c."taken_at"::timestamptz) as "bucket", c."org_id" as "org_id", c."kind" as "kind", count(*) as "events", sum(c."watts") as "watts_sum", max(c."watts") as "watts_max", sum(c."cost") as "cost_sum"
  from public.readings as c
  where c."taken_at" >= date_trunc('hour', $1) and c."deleted_at" is null
  group by 1, 2, 3
), gone as (
  delete from "public"."readings_hourly" as r where r."bucket" >= date_trunc('hour', $1) and not exists (select from fresh where fresh."bucket" = r."bucket" and fresh."org_id" = r."org_id" and fresh."kind" = r."kind")
)
insert into "public"."readings_hourly" ("bucket", "org_id", "kind", "events", "watts_sum", "watts_max", "cost_sum")
select "bucket", "org_id", "kind", "events", "watts_sum", "watts_max", "cost_sum" from fresh
on conflict ("bucket", "org_id", "kind") do update set "events" = excluded."events", "watts_sum" = excluded."watts_sum", "watts_max" = excluded."watts_max", "cost_sum" = excluded."cost_sum"
$buckets$;

select "rollups"."readings_hourly_refresh"('-infinity');

