update readings set watts = watts + 1 where taken_at >= '2026-11-07 10:00:00+00';
update readings set deleted_at = '2026-11-08 00:00:00+00' where taken_at >= '2026-11-07 14:00:00+00' and taken_at < '2026-11-07 15:00:00+00';
